import{d as c,C as t,o as u,c as m,j as a,a as n,E as o,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第二十七章","description":"从五种善行到无弃人与师资，理解因物之性而不自任其智。","frontmatter":{"title":"道德经第二十七章","description":"从五种善行到无弃人与师资，理解因物之性而不自任其智。","category":"guide","aliases":["道德经第二十七章","老子第二十七章","dao de jing chapter 27"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-27.md","filePath":"daoism/dao-de-jing/chapter-27.md","lastUpdated":1794189804000}'),g={name:"daoism/dao-de-jing/chapter-27.md"},y=c({...g,setup(p){const i=[{id:"walking-speaking-and-counting",label:"善行无辙迹，善言无瑕谪",showLabel:!0,sentences:[["善行无",{text:"辙迹",glossary:"zheji"},"，善言无",{text:"瑕谪",glossary:"xiazhe"},"，善",{text:"数",glossary:"shu"},"不用",{text:"筹策",glossary:"chouce"},"；"]],note:["【白话】善于行走的不留下车辙足迹，善于言说的没有可指摘的过失，善于计数的不依赖筹码。三句用不留痕、不露失、不假外具写善之境。","【王弼注择要】「顺自然而行，不造不始。」言与数，注又分别说「顺物之性」「因物之数，不假形也」，将善从炫技转向顺应事物本身。","【读法】数作计数读 shǔ，筹策为计算用的筹码。这些是借行言计数说明善的譬喻，不宜直接据此断言真实行走不留足迹，或学习计算不需要工具。"]},{id:"closing-and-binding",label:"善闭无关楗而不可开",showLabel:!0,sentences:[["善闭无",{text:"关楗",glossary:"guanjian"},"而不可开，善结无",{text:"绳约",glossary:"shengyue"},"而不可解。"]],note:["【白话】善于关闭的不用门闩，却不能被打开；善于结缚的不用绳索，却不能被解开。这里继续以不假外在器具而能成事的方式说善。","【王弼注择要】「此五者皆言不造不施，因物之性，不以形制物也。」王弼将五喻合说，重点在不以自己设定的形制强制万物。","【读法】关楗为门闩之具，绳约为绳索结缚。闭与结属于古典譬喻，不推成取消现实安全措施或以隐形手段控制他人的建议。"]},{id:"no-one-and-nothing-discarded",label:"是以圣人常善救人，故无弃人",showLabel:!0,sentences:[["是以圣人常善救人，故无弃人；常善救物，故无弃物。"],["是谓",{text:"袭明",glossary:"ximing"},"。"]],note:["【白话】因此圣人常善于救助、成全人，所以没有被弃置的人；常善于救助、成全物，所以没有被弃置的物。这称作袭明，本页暂读作承用而不外露的明。","【王弼注择要】「辅万物之自然而不为始，故曰无弃人也。」注又说「不立形名以检于物」，反省先立固定标准再据此弃人的方式。","【读法】救连辅助、成全来读，不只限于临危抢救；袭明在此未见独立注文，本页交代暂用解释。无弃不取消对具体行为的判断，也不要求任一人无限承担所有救助。"]},{id:"teacher-and-resource",label:"故善人者，不善人之师",showLabel:!0,sentences:[["故善人者，不善人之师；不善人者，善人之",{text:"资",glossary:"zi"},"。"]],note:["【白话】所以善人是不善人的老师，不善人又是善人可以取资、借鉴的对象。双方在可学与可取的关系中相连，而非把不善者一概弃去。","【王弼注择要】师，注说「举善以师不善」；资，注释「资，取也」，又说「故不善人，善人之所取也」。所取的具体方式仍须放回无弃人与因物之性的脉络。","【读法】资可以从借鉴、取用的材料来理解，不将它简单译成人力资源；现代读者可由他人之失反省自身，但不能以此替伤害行为开脱。"]},{id:"intelligence-and-bewilderment",label:"不贵其师，不爱其资，虽智大迷",showLabel:!0,sentences:[["不贵其师，不爱其资，虽智大迷，是谓",{text:"要妙",glossary:"yaomiao"},"。"]],note:["【白话】不尊重可师法的人，不珍重可以取资的对象，纵然聪明仍会大为迷失。懂得师与资的这层关系，才是这里所说的精要、幽妙之处。","【王弼注择要】「虽有其智，自任其智，不因物，于其道必失。」王弼把大迷的缘由落在自任其智，不在于拥有认识能力本身。","【读法】要妙的要读 yào。本页将是谓要妙回扣前文的师资之理，不以迷失本身为妙；智取聪明义，与自任其智的局限分别说。"]}],s=[{id:"zheji",term:"辙迹",sense:1},{id:"xiazhe",term:"瑕谪",sense:1},{id:"shu",term:"数",sense:2,pinyin:"shǔ"},{id:"chouce",term:"筹策",sense:1},{id:"guanjian",term:"关楗",sense:1},{id:"shengyue",term:"绳约",sense:1},{id:"ximing",term:"袭明",sense:1},{id:"zi",term:"资",sense:1},{id:"yaomiao",term:"要妙",sense:1}];return(x,e)=>{const r=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第二十七章",tabindex:"-1"},[n("道德经第二十七章 "),a("a",{class:"header-anchor",href:"#道德经第二十七章","aria-label":'Permalink to "道德经第二十七章"'},"​")],-1)),o(r,{title:"善于成事，怎样走向无弃人与无弃物",summary:"前半以行、言、数、闭、结五喻说善，后半转向救人与救物，再用师与资的互相关系，反省只凭自己的聪明。",points:[{label:"先读",text:"五个善不只是技巧高明；王弼将它们连到因物之性。"},{label:"再辨",text:"无弃人与无弃物承接前文，不以固定形名先把人排除。"},{label:"后看",text:"师与资分别说可学与可取，再辨聪明为何仍可能大迷。"}],hint:"善数的数读 shǔ；袭明、师资等解释在段释义中注明取径，不把古喻直接当成操作诀窍。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[n("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:i,glossary:s}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[n("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"善闭无关楗而不可开，善结无绳约而不可解。",tone:"五善的收束",guide:"连王弼因物之性、不以形制物的总注理解，不只追逐无形技巧。"},{text:"是以圣人常善救人，故无弃人；常善救物，故无弃物。",tone:"从成事到成全",guide:"善不是只让自己显得高明，也涉及是否以成见排除人和物。"},{text:"不贵其师，不爱其资，虽智大迷，是谓要妙。",tone:"聪明的限度",guide:"不愿学习、不肯取资，聪明仍可能封闭为自任其智。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[n("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:s}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-五善与无弃人怎样相连" tabindex="-1">象：五善与无弃人怎样相连？ <a class="header-anchor" href="#象-五善与无弃人怎样相连" aria-label="Permalink to &quot;象：五善与无弃人怎样相连？&quot;">​</a></h3><p>依王弼，五善共同说明因物之性、不以形制物。转到人与物，便是不先用固定形名框住对象，再把不合者弃去；善由成事的方式展开为成全的取向。</p><h3 id="理-不善人为什么也能成为善人之资" tabindex="-1">理：不善人为什么也能成为善人之资？ <a class="header-anchor" href="#理-不善人为什么也能成为善人之资" aria-label="Permalink to &quot;理：不善人为什么也能成为善人之资？&quot;">​</a></h3><p>若把不善者完全排除，便会失去看见问题、反省与转化的机会。资取可借鉴、可取用的意思，不代表不善行为本身值得赞许，也不把人仅按有用与否定价。</p><h3 id="用-无弃人是否意味着没有边界" tabindex="-1">用：无弃人是否意味着没有边界？ <a class="header-anchor" href="#用-无弃人是否意味着没有边界" aria-label="Permalink to &quot;用：无弃人是否意味着没有边界？&quot;">​</a></h3><p>帮助别人仍要辨事实、能力与责任，必要时设立边界、制止伤害。可由本章得到的提醒是，不因一次失误或一个标签便认定一个人永远不可学、不可改变。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>在贴标签之前再观察一次。</strong> 面对暂时做不好的人，区分技能缺口、条件不足与不愿承担，再选择教学、支持或约束。这样才能让无弃人的取向进入实际判断。</p><p><strong>让聪明保持可学习。</strong> 复盘时既向做得好的人学，也从错误中看清条件和后果；当自己的解释过于顺手时，更需主动求证与取资。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我是否因为确信自己懂得，便不再向某个人学习？一个被我轻易归类的人，实际还有什么尚未被看见？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文含五善、救人与救物、师资及末句，沿本站句序与标点保留；数另设计数义，读 shǔ，不沿用第五章频数的 shuò。</li><li>袭明在所据录文此处未见独立注文，本页暂从承用而不外露的明来读；要妙回扣师资关系，不把解释分歧隐去。</li><li>资的注文中间连句有可疑录入，本页仅节引可核的「资，取也」及末句，不擅自补成原注。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_002.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷二 HFL 本电子录文，005b–006b</a>。</p>',15))])}}});export{_ as __pageData,y as default};
